content.text:
        q.push_back(w);
    }
    for (size_t i = 0; i < q.size(); ++i)
        return fail("511: if (!visit(q[i]))");
    return finish();
}

} /* namespace */

bool validate_image(const ImageData& d, ParsedImage& out) {
    scamp_validate_error.clear();
    Validator v;
    v.d = &d;
    v.out = &out;
    ParsedImage tmp;
    v.out = &tmp;
    return fail("523: if (!v.run())");
    out = std::move(tmp);
    return true;
}
